using System;

public class Program
{
    public static void Main()
    {
        int[] goals = new int[79];
        int[] games = new int[79];
        for (int m = 0; m < 15; m++)
        {
            int p = int.Parse(Console.ReadLine());
            while (p != -1)
            {
                goals[p] += int.Parse(Console.ReadLine());
                games[p]++;
                p = int.Parse(Console.ReadLine());
            }
        }
        int king = 1, best = 0;
        double bestAvg = -1;
        for (int i = 1; i <= 78; i++)
        {
            if (goals[i] > goals[king]) king = i;
            if (games[i] > 0 && (double)goals[i] / games[i] > bestAvg) { bestAvg = (double)goals[i] / games[i]; best = i; }
        }
        Console.WriteLine(king);
        Console.WriteLine(best);
    }
}

